"""Two Sparse Witnesses Straddling the Density 3/2 Threshold.

Self-contained numerical exercise of the main density theorems:
  edgeFinset_card_le_of_maxDegree_two, maxDegree_two_edgeDensity_lt,
  IsAcyclic.card_edgeSet_add_one_le, acyclic_edgeDensity_lt_threshold, maxDegree_mono.
"""
from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from typing import FrozenSet, List, Tuple

Edge = FrozenSet[int]
THRESHOLD = Fraction(3, 2)


@dataclass(frozen=True)
class Graph:
    n: int
    edges: Tuple[Edge, ...]

    def degree(self, v: int) -> int:
        return sum(1 for e in self.edges if v in e)

    def max_degree(self) -> int:
        return max((self.degree(v) for v in range(self.n)), default=0)

    def density(self) -> Fraction:
        return Fraction(0) if self.n == 0 else Fraction(len(self.edges), self.n)


def path(n: int) -> Graph:
    return Graph(n, tuple(frozenset((i, i + 1)) for i in range(n - 1)))


def cycle(n: int) -> Graph:
    return Graph(n, tuple(frozenset((i, (i + 1) % n)) for i in range(n)))


def union(parts: List[Graph]) -> Graph:
    off, edges = 0, []
    for g in parts:
        edges += [frozenset({a + off for a in e}) for e in g.edges]
        off += g.n
    return Graph(off, tuple(edges))


def is_forest(g: Graph) -> bool:
    parent = list(range(g.n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for e in g.edges:
        a, b = tuple(e)
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        parent[ra] = rb
    return True


def main() -> None:
    samples = [path(5), cycle(3), cycle(7), union([cycle(4), cycle(5)]),
               union([path(3), cycle(6)])]
    print("Bounded-degree-<=2 witness:")
    for g in samples:
        assert g.max_degree() <= 2
        assert len(g.edges) <= g.n               # handshaking bound |E| <= |V|
        assert g.density() < THRESHOLD           # density < 3/2
        print(f"  |V|={g.n} |E|={len(g.edges)} rho={g.density()} forest={is_forest(g)}")

    print("Cycles realize tightness |E| = |V| (density 1, not forests):")
    for n in (3, 5, 8):
        c = cycle(n)
        assert len(c.edges) == c.n and not is_forest(c) and c.density() == 1
        print(f"  C_{n}: rho={c.density()} tight, forest={is_forest(c)}")

    print("Forest witness |E|+1 <= |V|, density < 3/2:")
    for g in [path(6), union([path(2), path(3)])]:
        assert is_forest(g) and len(g.edges) + 1 <= g.n and g.density() < THRESHOLD
        print(f"  |V|={g.n} |E|={len(g.edges)} rho={g.density()}")

    print("All witness checks passed.")


if __name__ == "__main__":
    main()

