function is_minimal_obstruction(m, in_C, proper_minors):
    if in_C(m): return false
    for x in proper_minors(m):
        if not in_C(x): return false
    return true

function single_forbidden_minor(C_members, in_C, proper_minors):
    O := { m in C_members | is_minimal_obstruction(m, in_C, proper_minors) }
    return |O| == 1
